function validate([grid]) {
  const m = grid.length;
  if (m < 1 || m > 100000) return 'grid needs 1 to 10^5 rows.';
  const n = grid[0].length;
  if (n < 1 || n > 100000) return 'Each row needs 1 to 10^5 values.';
  if (grid.some(row => row.length !== n)) return 'All rows must have the same length.';
  if (m * n < 2 || m * n > 100000) return 'grid needs between 2 and 10^5 cells.';
  if (grid.some(row => row.some(v => v < 1 || v > 100000))) return 'Each value is between 1 and 10^5.';
  return null;
}

