function canPartitionGrid(grid) {
  const m = grid.length;
  const n = grid[0].length;
  const rowSums = new Array(m).fill(0);
  const colSums = new Array(n).fill(0);
  let total = 0;
  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      rowSums[i] += grid[i][j];
      colSums[j] += grid[i][j];
      total += grid[i][j];
    }
  }
  // Horizontal cut below row i: rows 0..i form the top block.
  let top = 0;
  for (let i = 0; i < m - 1; i++) {
    top += rowSums[i];
    if (top * 2 === total) {
      return true;
    }
  }
  // Vertical cut right of column j: columns 0..j form the left block.
  let left = 0;
  for (let j = 0; j < n - 1; j++) {
    left += colSums[j];
    if (left * 2 === total) {
      return true;
    }
  }
  return false;
}

