function canPartitionGrid(grid) {
  // Try every cut and add up both blocks from scratch.
  const m = grid.length;
  const n = grid[0].length;
  const sumWhere = keep => {
    let sum = 0;
    for (let i = 0; i < m; i++) for (let j = 0; j < n; j++) if (keep(i, j)) sum += grid[i][j];
    return sum;
  };
  for (let r = 1; r < m; r++) if (sumWhere(i => i < r) === sumWhere(i => i >= r)) return true;
  for (let c = 1; c < n; c++) if (sumWhere((i, j) => j < c) === sumWhere((i, j) => j >= c)) return true;
  return false;
}

