function generate(rand, size) {
  const between = (low, high) => low + Math.floor(rand() * (high - low + 1));
  let m;
  let n;
  if (size === 'large') {
    [m, n] = [[100, 100], [100, between(1, 100)], [between(1, 100), 100], [between(50, 100), between(50, 100)]][between(0, 3)];
  } else {
    do {
      m = between(1, 4);
      n = between(1, 4);
    } while (m * n < 2);
  }
  const highest = rand() < 0.5 ? 9 : 100000;
  const grid = Array.from({ length: m }, () => Array.from({ length: n }, () => between(1, highest)));
  if (rand() < 0.6) {
    // Balance one chosen cut: lower cells of the heavier block (to at least 1) or raise cells of the lighter one.
    const horizontal = n === 1 || (m > 1 && rand() < 0.5);
    const at = horizontal ? between(1, m - 1) : between(1, n - 1);
    const first = (i, j) => (horizontal ? i < at : j < at);
    let diff = 0;
    for (let i = 0; i < m; i++) for (let j = 0; j < n; j++) diff += first(i, j) ? grid[i][j] : -grid[i][j];
    for (let i = 0; i < m && diff !== 0; i++) {
      for (let j = 0; j < n && diff !== 0; j++) {
        const heavy = (diff > 0) === first(i, j);
        const change = Math.min(Math.abs(diff), heavy ? grid[i][j] - 1 : 100000 - grid[i][j]);
        grid[i][j] += heavy ? -change : change;
        diff -= Math.sign(diff) * change;
      }
    }
    // Sometimes nudge one cell so that the balanced cut just misses.
    if (rand() < 0.3) {
      const i = between(0, m - 1);
      const j = between(0, n - 1);
      const delta = between(1, 2);
      grid[i][j] += grid[i][j] + delta <= 100000 ? delta : -delta;
    }
  }
  return [grid];
}
